def test_every_subscription_is_allowed_or_refused_and_none_is_both():
    allowed, refused = set(roles.PORTAL_CMDS), set(roles.PORTAL_REFUSED)
    assert not allowed & refused
    later = set(roles.NOT_ON_PORTAL)  # 1.7.1: refused as "anything else"; 1.7.2 (revision 3) names layover/note
    assert not later & (allowed | refused) and "layover/note" in refused
    assert set(roles.SUBS) == allowed | refused | later  # every MQTT command topic an instance takes is classified
    for s in later:
        assert roles.portal_sub(s) is None and roles.FEATURES[roles.SUBS[s]][1] is False, s
    for s in allowed:
        assert roles.FEATURES[roles.SUBS[s]][1] is True, s  # offered on a portal
    for s in refused:
        f = roles.SUBS[s]
        # 1.7.2 (revision 3, F#78): recall/set is a core feature the portal no longer offers (the admin's forward only)
        assert f == roles.INTERNAL or roles.FEATURES[f][1] is False or s in roles.COMMAND_REMOVED, s
        assert roles.portal_sub(s) is None, s
    assert "recall/set" in refused and "recall/set" not in allowed and "upload/decide" in refused
    assert "upload/pdf" in allowed and roles.portal_sub("upload/pdf") == "upload/pdf"
    for f in ("value", "comm_why", "pay", "captain", "contact", "detail_url", "url", "picked_by", "emp", "name",
              "title", "narrative", "text", "reporter", "kind"):
        assert f not in roles.EVENT_FIELDS, f  # plan risk K1: pay and personal data never leave the instance
    assert {"comm", "month_rule"} <= set(roles.EVENT_FIELDS)


def test_signed_samples_verify_and_bad_ones_fail():
    fx = _fx()
    pub = fx["test_key"]["public_key"]
    for s in fx["samples"]["envelopes"]:
        kind = PT.kind_of(s["file"])
        assert kind and PT.verify(pub, s["envelope"], kind, "demo") == s["envelope"]["payload"]
        json.loads(s["envelope"]["payload"])
    for b in fx["samples"]["bad_envelopes"]:
        kind = PT.kind_of(b.get("file", "state.json"))
        with pytest.raises(PT.PortalError):
            PT.verify(pub, b["envelope"], kind, "demo", after=b.get("after"))
    ev = json.loads(fx["samples"]["envelopes"][2]["envelope"]["payload"])["events"][0]
    assert set(ev["data"]) <= set(roles.EVENT_FIELDS) and "Doe" not in json.dumps(ev)


def test_command_samples_match_the_spool(tmp_path):
    """Every sample through its own Spool (a new one each time: the 30-a-minute cap is not what a sample tests)."""
    fx = _fx()
    in_dir = tmp_path / "in"
    in_dir.mkdir()
    for s in fx["samples"]["commands"]["accepted"]:
        sp = PT.Spool("demo", now=lambda: 1763600000.5)
        (in_dir / s["name"]).write_text(json.dumps(s["cmd"]))
        cid, sub, payload = sp.take(str(in_dir / s["name"]))
        assert (cid, sub, payload) == (s["cmd"]["id"], s["cmd"]["sub"], s["cmd"]["payload"])
    for s in fx["samples"]["commands"]["refused"]:
        sp = PT.Spool("demo", now=lambda: 1763600000.5)
        (in_dir / s["name"]).write_text(json.dumps(s["cmd"]))
        with pytest.raises(PT.PortalError):
            sp.take(str(in_dir / s["name"]))
    assert os.listdir(in_dir) == []


def test_ticket_samples_match_check_ticket():
    """1.7.0: each ticket sample, accepted or refused, through check_ticket alone: the refused ones for the shape
    (the sub is allowed), so HOM's generic checkTicket must refuse each for the same rules."""
    fx = _fx()
    acc = [s for s in fx["samples"]["commands"]["accepted"] if s["cmd"]["sub"].startswith("ticket/")]
    ref = [s for s in fx["samples"]["commands"]["refused"] if s["cmd"]["sub"].startswith("ticket/")]
    assert {s["cmd"]["sub"] for s in acc} == {s["cmd"]["sub"] for s in ref} == set(roles.TICKET_CMDS)
    for s in acc:
        assert isinstance(PT.check_ticket(s["cmd"]["sub"], s["cmd"]["payload"]), dict), s
    for s in ref:
        with pytest.raises(PT.PortalError):
            PT.check_ticket(s["cmd"]["sub"], s["cmd"]["payload"])
    whys = {s["why"] for s in ref}
    for w in ("worker action fixed", "worker action triage", "worker action progress", "worker action close",
              "note with no text", "new with an inline image", "new names a reporter", "new with images 2.5",
              "image i over n", "image data is a data URL", "image data with a trailing newline", "id not FW-nnnn",
              "new title over 200 code points"):
        assert w in whys, w
    by = {json.loads(s["cmd"]["payload"]).get("title", "") for s in acc if s["cmd"]["sub"] == "ticket/new"}
    cap = [t for t in by if len(t) == 200]
    assert cap and any(ord(c) > 0xFFFF for c in cap[0])  # code points, not UTF-16 units (JS length would say 201)
    assert any('"images":2.0' in s["cmd"]["payload"] for s in acc)  # a whole float is a whole number (JS cannot tell)


OWN_FOLDER = ("finds", "school", "versions", "pickers", "recall", "pilotver", "tickets", "pilotdb")  # pairings is shared


def _remap(url, pilot="demo"):
    """What the portal's shim does with a card's file URL (a reference for HOM's shim.test.mjs). 1.7.0: a kind kept
    in the pilot's own folder maps only from his folder (the admin's no-folder file and another pilot's give None)."""
    m = re.fullmatch(r"/local/flight-watcher/(?:([a-z0-9_]+)/)?([a-z]+)_([^?]+)\.json(?:\?.*)?", url)
    if not m:
        return None
    who, kind, rest = m.group(1), m.group(2), m.group(3)
    if kind not in roles.FILE_KINDS or (kind in OWN_FOLDER and who != pilot) or (kind not in OWN_FOLDER and who):
        return None
    pat = roles.FILE_KINDS[kind]
    if not pat:
        return f"/fw/api/file/{kind}", kind, ""
    arg = re.match(pat, rest).group(0)
    return f"/fw/api/file/{kind}/{arg}", kind, arg


def test_file_url_samples():
    fx = _fx()
    kinds = set()
    for s in fx["samples"]["file_urls"]:
        assert _remap(s["url"]) == (s["api"], s["kind"], s["arg"]), s
        kinds.add(s["kind"])
    assert kinds == set(roles.FILE_KINDS)
    assert fx["samples"]["file_urls_refused"]
    for s in fx["samples"]["file_urls_refused"]:  # 1.7.0: the admin's tickets list and another pilot's folder
        assert _remap(s["url"]) is None, s


def test_doc_names_everything_in_the_contract():
    doc = open(DOC, encoding="utf-8").read()
    assert chr(0x2014) not in doc
    assert "| contract 1 (`fwp` 1) | 1.6.0 | 1.6.0 |" in doc
    assert "| contract 1 rev 2 (`fwp` 1) | 1.7.0 | 1.8.0 | tickets on the portal |" in doc
    assert "| contract 1 rev 3 (`fwp` 1) | 1.7.2 | 1.8.2 |" in doc  # 1.7.2
    assert "| contract 1 rev 4 (`fwp` 1) | 1.7.9 | 1.9.0 |" in doc  # 1.7.9
    for s in roles.PORTAL_CMDS:
        assert f"`{s if s != 'rule/+/live/set' else 'rule/<id>/live/set'}`" in doc, s
    for s in roles.PORTAL_REFUSED:
        assert f"`{s}`" in doc, s
    for k in roles.PORTAL_EVENTS + roles.MACHINE_EVENTS + roles.OWN_EVENTS:
        assert f"`{k}`" in doc, k
    for f in roles.EVENT_FIELDS + tuple(x for v in roles.EVENT_KIND_FIELDS.values() for x in v):
        assert re.search(r"\b%s\b" % f, doc), f
    for k in roles.FILE_KINDS:
        assert f"`{k}`" in doc, k
    for k in roles.PREF_KEYS:
        assert f"`{k}`" in doc, k
    for word in ("256 KB", "2 MB", "64 KB", "8 MB", "1 MB", "300 s", "600 s", "0640", "0750", "0700", "0755",
                 "2061", "portal signing key ed25519:", "fw_signing_key", "https://ntfy.sh/<topic>",
                 "portal_contract_v1.json", "fwportal/contract/v1.json",
                 # 1.7.0 (Release C)
                 "revision 2", "check_ticket", "checkTicket", "ticket_rules", "pilot_ticket_limits", "re-encode",
                 "60000", "1.5 MB", "untrusted", "tickets_fixed_seen.json", "priority 2",
                 # 1.7.2 (revision 3)
                 "revision 3", "check_shape", "since_revision", "pilot_upload_limits", "pilot_upload_checks",
                 "kind_fields", "%%EOF", "setrlimit", "30 s", "512 MB", "at least 100 pairings", "quarantine",
                 "provenance.json", "upload/decide", "event/", "time-sensitive", "Approve", "Reject", "Remove",
                 "sensor.<prefix>_pilot_uploads", "Fit\n  Fits", "SCHEDULE_UNREAD_H", "HOM 1.8.2",
                 # 1.7.9 (revision 4)
                 "revision 4", "HOM 1.9.0", "sensor.<prefix>_pilotdb", "pilotdb_rules", "pilotdb_answers",
                 "inbox/<name>/", "compare-and-set",
                 "Busy: try again in a minute", "never set by Claude", "stats.json", "ai_notes",
                 "labeled AI", "min_pickups: 3", "note_max: 600", "32 KB", "F#107", "trade/set", "masks.contact_only_in",
                 "portal.PILOTDB_FILE_KEYS", "union_id",
                 # 1.7.10 (Ryan's decisions of Nov 15): shared 100%, on by default, the choices outside the database
                 "shared with James 100%", "every live record", "on by default", "pilotdb_switches.json",
                 "EXPORT_HARD", "7 MiB", "either order", "A pilot's uploads", "that pilot is not in Ryan's pilot database"):
        assert word in doc, word
    for a in roles.PILOT_TICKET_ACTIONS:
        assert f"`{a}`" in doc, a
    # the two sentences 1.6.2 left behind (section 6 named only a token; 5.3 seeded prefs from the HA helpers)
    assert "topic only" in doc and "seeded once from the HA helpers" not in doc


# ---------------------------------------------------------------- 1.7.9 (revision 4): the shared pilot database
def test_revision_4_tables_are_in_the_fixture():
    fx = _fx()
    cm = fx["commands"]
    assert {"pilotdb/note", "pilotdb/edit"} <= set(cm["allowed"])
    assert cm["since_revision"]["pilotdb/note"] == cm["since_revision"]["pilotdb/edit"] == 4
    assert cm["pilotdb_note_limits"] == roles.PILOTDB_NOTE_LIMITS
    assert cm["pilotdb_answers"] == list(roles.PILOTDB_ANSWERS) and cm["pilotdb_rules"] == list(PT.PILOTDB_RULES)
    assert set(cm["shapes"]) == {"pilot/set", "upload/pdf", "pilotdb/note", "pilotdb/edit"}
    note, edit = cm["shapes"]["pilotdb/note"], cm["shapes"]["pilotdb/edit"]
    assert note["keys"] == ["op", "pid", "entry", "base", "text", "rid"] and note["required"] == ["op", "pid", "rid"]
    assert note["fields"]["op"]["values"] == ["add", "retract", "field"]
    assert edit["fields"]["op"]["values"] == ["set", "unset"]
    assert edit["fields"]["field"]["values"] == list(roles.PILOTDB_EDIT_FIELDS)
    for shape in (note, edit):  # no author, no employee number and no name can be sent
        assert not {"by", "author", "emp", "name"} & set(shape["keys"])
        # only what the generic checkers on both sides already know
        assert set(shape) <= {"keys", "required", "fields", "nonempty_when", "any_of", "le"}
        assert {f["type"] for f in shape["fields"].values()} <= {"text", "int", "enum"}
    assert fx["file_kinds"]["pilotdb"] == "" and fx["synthesized_states"]["pilotdb"] == "sensor.<prefix>_pilotdb"
    assert fx["revisions"]["4"].startswith("Flight Watcher 1.7.9, HOM 1.9.0")
    assert fx["tabs"] == ["watcher", "schedule", "pilot", "recall", "settings", "tickets"]  # unchanged
    # contact is still dropped from every state read from HA; 1.7.10: phones and emails are in the pilotdb file's
    # records (Ryan, Nov 15: shared 100%), never in a state
    assert fx["masks"]["drop"] == ["contact"] == list(PT.MASK_DROP) and "pilotdb file" in fx["masks"]["contact_only_in"]
    pd = fx["pilotdb"]
    assert pd["file"]["keys"] == PT.PILOTDB_FILE_KEYS and pd["state"]["keys"] == PT.PILOTDB_STATE_KEYS
    assert pd["edit_fields"] == list(roles.PILOTDB_EDIT_FIELDS) and set(pd["edit_values"]) == set(pd["edit_fields"])
    assert pd["inbox"]["file_re"] == PT.INBOX_NAME_RE.pattern and pd["inbox"]["max_bytes"] == 32 * 1024
    assert "by" in pd["inbox"]["body"] and "on by default" in pd["share"] and "Claude never" in pd["share"]
    ai = pd["ai"]
    assert ai["min_pickups"] == 3 and ai["note_max"] == 600 and "on by default" in ai["switch"]
    assert ai["stats_path"] == "/share/flight_watcher/pilotdb/ai/stats.json"
    assert ai["in_dir"] == "/share/flight_watcher/pilotdb/ai/in"
    assert not {"name", "emp", "pid", "sen", "doh", "pairing", "at"} & set(ai["stats_keys"]["stats"])
    assert ai["stats_keys"]["pilot"] == ["id", "stats"] and ai["notes_keys"]["note"] == ["id", "text"]
    # every limit a card shows is in the limits
    assert set(PT.pilotdb_limits()) <= set(roles.PILOTDB_NOTE_LIMITS)
    # the manifest sample, the state sample and the file sample
    man = json.loads(fx["samples"]["envelopes"][0]["envelope"]["payload"])
    assert {"pilotdb/note", "pilotdb/edit"} <= set(man["mqtt_subs"]) and "pilotdb" in man["files"]
    st = json.loads(fx["samples"]["envelopes"][1]["envelope"]["payload"])["states"]["sensor.flight_watcher_demo_pilotdb"]
    assert st["state"] == "on" and set(st["attributes"]) == set(PT.PILOTDB_STATE_KEYS["attributes"])
    assert set(st["attributes"]["shown"]) == {"emp", "pid"} <= set(PT.PILOTDB_STATE_KEYS["shown"])
    f = next(json.loads(e["envelope"]["payload"]) for e in fx["samples"]["envelopes"] if e["file"] == "files/pilotdb.json")
    assert set(f) <= set(PT.PILOTDB_FILE_KEYS["top"]) and set(f["records"][0]) <= set(PT.PILOTDB_FILE_KEYS["record"])
    text = json.dumps(f)
    assert f["records"][0]["union_id"] == "424242" and set(f["records"][0]["ai_note"]) == {"text", "model", "at"}  # 1.7.10
    # 1.7.10: every record with every field, and every key of the sample is a whitelisted one
    r0 = f["records"][0]
    assert (r0["emp"], r0["base"], r0["emails"]) == ("10001", "HNL", ["jane.doe@example.com"])
    assert set(r0["phones"][0]) == set(PT.PILOTDB_FILE_KEYS["phone"])
    assert set(r0["pickups"]) == set(PT.PILOTDB_FILE_KEYS["pickups"])
    assert set(r0["pickups"]["rows"][0]) == set(PT.PILOTDB_FILE_KEYS["pickup"])
    assert set(r0["pickups"]["summary"]) == set(PT.PILOTDB_FILE_KEYS["pickup_summary"])
    assert len(f["records"]) == f["count"] == 2 and '"contact"' not in text
    assert len(text.encode()) < PT.CAPS["file"]


def test_pilotdb_samples_match_check_shape():
    """Every pilotdb sample through check_shape alone: the refused ones for the shape (the sub is allowed), so HOM's
    generic checker must refuse each for the same rules."""
    fx = _fx()
    subs = ("pilotdb/note", "pilotdb/edit")
    acc = [s for s in fx["samples"]["commands"]["accepted"] if s["cmd"]["sub"] in subs]
    ref = [s for s in fx["samples"]["commands"]["refused"] if s["cmd"]["sub"] in subs]
    assert {s["cmd"]["sub"] for s in acc} == {s["cmd"]["sub"] for s in ref} == set(subs)
    assert all(s["name"].startswith("17636000007") for s in acc) and all(s["name"].startswith("17636000008") for s in ref)
    for s in acc:
        assert isinstance(PT.check_shape(s["cmd"]["sub"], s["cmd"]["payload"]), dict), s
    for s in ref:
        with pytest.raises(PT.PortalError):
            PT.check_shape(s["cmd"]["sub"], s["cmd"]["payload"])
    whys = {s["why"] for s in ref}
    for w in ("note op edit", "note without rid", "note without pid", "note names an author",
              "note names an employee number", "note text over 4000 code points", "note text with a bidi override",
              "note text with a NUL", "retract without entry", "field without base", "field base not hex",
              "add with empty text", "note op a number", "edit an unknown field", "edit rev as text",
              "edit set without a value", "edit value a list", "edit names an author"):
        assert w in whys, w
    ops = {(s["cmd"]["sub"], json.loads(s["cmd"]["payload"])["op"]) for s in acc}
    assert ops == {("pilotdb/note", "add"), ("pilotdb/note", "retract"), ("pilotdb/note", "field"),
                   ("pilotdb/edit", "set"), ("pilotdb/edit", "unset")}
    cap = [json.loads(s["cmd"]["payload"]).get("text", "") for s in acc]
    assert any(len(t) == 4000 and ord(t[0]) > 0xFFFF for t in cap)  # code points, not UTF-16 units
    assert any(json.loads(s["cmd"]["payload"]).get("base") == "000000000000" and
               json.loads(s["cmd"]["payload"]).get("text") == "" for s in acc)
    assert any('"rev":7.0' in s["cmd"]["payload"] for s in acc)
    # Ryan's own ops are no portal sub
    other = [s["cmd"]["sub"] for s in fx["samples"]["commands"]["refused"] if s["cmd"]["sub"].startswith("pilotdb/")
             and s["cmd"]["sub"] not in subs]
    assert other == ["pilotdb/share", "pilotdb/forget", "pilotdb/hide", "pilotdb/ai"]
    for sub in other:
        assert roles.portal_sub(sub) is None


def test_the_swap_alert_is_a_portal_event_built_from_whitelisted_fields():
    """1.7.9 (revision 4, F#107): a new swap idea. The pilot opts in by marking a trip would trade (trade/set)."""
    fx = _fx()
    assert "swap" in roles.PORTAL_EVENTS and fx["events"]["views"]["swap"] == "watcher"
    assert fx["events"]["kind_fields"]["swap"] == ["for_trip", "for_date", "soft_gain", "credit_gain", "src"]
    ev = json.loads(fx["samples"]["envelopes"][2]["envelope"]["payload"])["events"][-1]
    assert ev["kind"] == "swap" and ev["view"] == "watcher" and ev["priority"] == 3
    assert ev["title"] == "Swap idea: H9002 20NOV-22NOV for your H9001"
    assert ev["body"] == ("3 days, layover SYD. Credit 15:20 (+4:50). Soft time +0:40. In open time. See it on the "
                          "Watcher tab. Nothing is ever submitted for you: FLICA stays read only.")
    assert set(ev["data"]) <= set(roles.EVENT_FIELDS) | set(roles.EVENT_KIND_FIELDS["swap"])
    text = json.dumps(ev)
    for bad in ("why", "detail_url", "example.invalid", "would_submit", "DRAFT", "gain_h", "grid"):
        assert bad not in text, bad
    # another kind's payload never brings the swap fields along
    d = PT.event_data("new_pairing", {"pairing": "H9001", "for_trip": "H9002", "soft_gain": "+1:00"})
    assert d == {"pairing": "H9001"}
    import ntfy
    assert ntfy.plain_text(ev) == ("Swap idea H9002 20NOV-22NOV", "Open your Flight Watcher portal for the details.")
